\begin{proof} Recall the definition of the set $U$ in \cref{eq:buckets}. We prove \cref{lem:no} by showing that with constant probability over the terms $\pmb{t}$ and the random function $\pmb{r} \colon U \to \{0,1\}$, there exists a collection $L$ of $\Omega(3^n)$ disjoint co-linear triples $(x,y,z)$ such that $x,z \in S_{\pmb{t},\pmb{r}}$, $y \notin S_{\pmb{t},\pmb{r}}$, and $y = \frac{1}{2}(x+z)$. The existence of such a set implies that $\eps(S_{\pmb{t},\pmb{r}}) \geq \frac{1}{3}|L| \cdot 3^{-n} = \Omega(1)$ since the membership of at least one point from each of these triples would need to changed in order to make the set convex.

We first show that there is a large collection $T$ of disjoint co-linear triples lying in $\midlayers(\sqrt{n})$. Then, by \cref{clm:highprob_vertex} and fact that each point in $U$ is included in the set $S_{\pmb{t},\pmb{r}}$ with probability $1/2$, we can argue that with constant probability, a constant fraction of the triples in $T$ will be violations of convexity. 

\begin{claim} \label{clm:triples} There exists a set $T$ of $\Omega(3^n)$ disjoint co-linear triples $(x,y,z)$ such that (a) $x,y,z \in \midlayers(\sqrt{n})$, and (b) $y = \frac{1}{2}(x+z)$. \end{claim}
\begin{proof} Given $z \in \zpm^{n-1}$ and $b \in \zpm$, let $(b,z) \in \zpm^n$ denote the point whose first coordinate is $b$ and the rest of the coordinates are given by $z$. Consider the set of disjoint triples 
\begin{align*} \label{eq:triples}  
    T := \left\{((-1,z),(0,z),(+1,z)) \colon z \in \zpm^{n-1} \text{ such that } \norm{z}_1 \in \left[\frac{2n}{3} - \sqrt{n}, \frac{2n}{3} + \sqrt{n} - 1\right]\right\} \text{.}
\end{align*}
Observe that every triple $(x,y,z)$ is contained in $\midlayers(\sqrt{n})$ and clearly $y = \frac{1}{2}(x+z)$. We use the following fact to lower bound $|T|$. This fact follows from an application of Stirling's approximation.
\begin{fact} For any $N$ and $\ell \in [-O(\sqrt{N}),O(\sqrt{N})]$, we have ${N \choose \frac{2N}{3} + \ell} = \Theta\left(\frac{1}{\sqrt{N}} \cdot \frac{3^N}{2^{2N/3}+\ell}\right)$. \end{fact}
By the above fact, 
\[
|T| = \sum_{\ell = -\sqrt{n}}^{\sqrt{n}-1} {n-1 \choose \frac{2n}{3} + \ell} 2^{2n/3+\ell} = \sum_{\ell = -\sqrt{n}}^{\sqrt{n}-1} \Omega\left(\frac{1}{\sqrt{n-1}} \cdot \frac{3^{n-1}}{2^{2(n-1)/3 + \ell}}\right) 2^{2n/3 + \ell} = \Omega(3^n)
\]
and this completes the proof of the claim. \end{proof}

Let $T$ denote the set of $\Omega(3^n)$ disjoint co-linear triples in $\midlayers(\sqrt{n})$ given by \cref{clm:triples}. We will need the following claim which shows that triples in $T$ are contained in $U$ with constant probability. 

\begin{claim} \label{clm:highprob_vertex} For any $(x,y,z) \in T$, we have $\pr_{\pmb{t}}[x,y,z \in U] \geq \frac{1}{1,000,000}$. \end{claim}

\begin{proof} By definition of $T$ we have $x,y,z \in \midlayers(\sqrt{n})$ and $x_1 = +1$, $y_1 = 0$, $z_1 = -1$ and $x_j = y_j = z_j$ for all $j \in [2,n]$. Recall the distribution over the terms $\bt = (t^{(1)},\ldots,t^{(N)})$ defined in \cref{sec:distributions}. Note that $\pr_{t^{(i)}}[t^{(i)} \preceq y] = (\frac{\norm{y}_1}{2n})^{\sqrt{n}}$ since $t^{(i)} \preceq y$ if and only if each of the $\sqrt{n}$ non-zero coordinates $a$ of $t^{(i)}$ (a) is chosen as one of the non-zero coordinates of $y$ which happens with probability $\norm{y}/n$ and (b) $t^{(i)}_a$ is set to $y_a$ which happens with probability $1/2$. Also note that for a term $t^{(i)}$, we have $t^{(i)} \prec y$ implies $t^{(i)} \prec x,z$. Therefore,
\begin{align} \label{eq:term-mass}
    \pr_{\pmb{t}}[x,y,z \in U_i] &= \pr_{t^{(i)}}[t^{(i)} \preceq x,y,z] \cdot \prod_{j \neq i} \pr_{t^{(j)}}[t^{(j)} \not\preceq x,y,z] \nonumber \\
    &= \pr_{t^{(i)}}[t^{(i)} \preceq y] \cdot \prod_{j \neq i} \pr_{t^{(j)}}[t^{(j)} \not\preceq x,z] \nonumber \\
    &= \pr_{t^{(i)}}[t^{(i)} \preceq y] \cdot \prod_{j \neq i} \left(1 - \pr_{t^{(j)}}[(t^{(i)} \preceq x) \vee (t^{(i)} \preceq z)]\right)\text{.}
\end{align}
The first term is lower bounded by
\begin{align} \label{eq:lower-bound}
    \pr_{t^{(i)}}[t^{(i)} \preceq y] = \left(\frac{\norm{y}_1}{2n}\right)^{\sqrt{n}} \geq \left(\frac{\frac{2n}{3}-\sqrt{n}}{2n}\right)^{\sqrt{n}} = \frac{1}{3^{\sqrt{n}}}\left(1 - \frac{3}{2\sqrt{n}}\right)^{\sqrt{n}} \geq \frac{e^{-3/2-o(1)}}{N} \geq \frac{1}{5N} \text{.}
\end{align}
To lower bound the second term, observe that 
\begin{align} \label{eq:upper-bound1}
    \pr_{t^{(i)}}[t^{(i)} \preceq x] = \left(\frac{\norm{x}_1}{2n}\right)^{\sqrt{n}} \leq \left(\frac{\frac{2n}{3}+\sqrt{n}}{2n}\right)^{\sqrt{n}} = \frac{1}{3^{\sqrt{n}}}\left(1 + \frac{3}{2\sqrt{n}}\right)^{\sqrt{n}} \leq \frac{e^{3/2}}{N} \leq \frac{5}{N}
\end{align}
and the same bound holds for the point $z$. Therefore, by a union bound $\pr_{t^{(i)}}[(t^{(i)} \preceq x) \vee (t^{(i)} \preceq z)] \leq 10/N$. Plugging this bound along with \cref{eq:lower-bound} into \cref{eq:term-mass} and summing over all $i \in [N]$ yields
\begin{align*}
    \pr_{\pmb{t}}[x,y,z \in U] &= \sum_{i=1}^N \pr_{t^{(i)}}[t^{(i)} \preceq y] \cdot \prod_{j \neq i} \left(1 - \pr_{t^{(j)}}[(t^{(i)} \preceq x) \vee (t^{(i)} \preceq z)]\right) \geq N \cdot \frac{1}{5N} \cdot \left(1 - \frac{10}{N}\right)^{N}
\end{align*}
which is at least $\frac{1}{1,000,000}$ and this completes the proof. \end{proof}

Now, for a set $S_{\pmb{t},\pmb{r}} \sim \Dno$, let 
\[
T_{\mathsf{viol}} = \{(x,y,z) \colon x,z \in S_{\pmb{t},\pmb{r}} \text{ and } y \notin S_{\pmb{t},\pmb{r}}\}
\]
denote the set of triples in $T$ that are violations of convexity for $S_{\pmb{t},\pmb{r}}$. By definition of $\Dno$ and using \cref{clm:highprob_vertex}, for any fixed $(x,y,z) \in T$, we have 
\begin{align*}
    \pr[(x,y,z) \in T_{\mathsf{viol}}] = \pr_{\pmb{t}}[x,y,z \in U] \cdot \pr_{\pmb{r}}[\pmb{r}(x) = \pmb{r}(z) = 1, \pmb{r}(y) = 0 ~|~ x,y,z \in U] \geq \frac{1}{8,000,000}.
\end{align*} 
Therefore, $\Exp_{\pmb{t},\pmb{r}}[|T\setminus T_{\mathsf{viol}}|] \leq |T|(1-\frac{1}{8,000,000})$ and so by Markov's inequality
\begin{align*}
    \pr_{\pmb{t},\pmb{r}}\left[|T_{\mathsf{viol}}| \leq \frac{|T|}{8,000,000^2}\right] &\leq \pr_{\pmb{t},\pmb{r}}\left[|T \setminus T_{\mathsf{viol}}| \geq |T|\left(1-\frac{1}{8,000,000^2}\right)\right] \\
    &= \pr_{\pmb{t},\pmb{r}}\left[|T \setminus T_{\mathsf{viol}}| \geq |T|\left(1-\frac{1}{8,000,000}\right)\left(1+\frac{1}{8,000,000}\right)\right] \\
    &\leq \pr_{\pmb{t},\pmb{r}}\left[|T \setminus T_{\mathsf{viol}}| \geq \Exp_{\pmb{t},\pmb{r}}[|T\setminus T_{\mathsf{viol}}|]\left(1+\frac{1}{8,000,000}\right)\right] \\
    &\leq \frac{1}{1+\frac{1}{8,000,000}} = 1 - \frac{1}{8,000,001} \text{.}
\end{align*}
Finally, since $|T| = \Omega(3^n)$, this gives us
\begin{align*}
    \pr_{\pmb{t},\pmb{r}}\left[\eps(S_{\pmb{t},\pmb{r}}) \geq \Omega(1)\right] \geq \pr_{\pmb{t},\pmb{r}}\left[|T_{\mathsf{viol}}| \geq \frac{|T|}{8,000,000^2}\right] \geq \frac{1}{8,000,001}
\end{align*}
and this completes the proof of \cref{lem:no}. \end{proof}
